"""The replay file (.fzrp): its constants, the version a race's features make, and a file's parts as far as
the file has them (parse, read). Every number big-endian. It judges nothing: what a tool refuses is its own
(protocol/formats.md section 1)."""
import struct

MARK = b"FZRP"
FRAMES_MARK = b"FZRF"
LINEUP_MARK = b"FZRL"
RESULTS_MARK = b"FZRS"
VERSION_PLAIN = 2  # a race of the disc's own car data and none of the features below
VERSION_STATS = 3  # the race ran on a stat pack (the header's match.setup.stats)
VERSION_CUSTOM = 4  # a seat raced a custom machine (a seat's match.setup.seats[].custom)
VERSION_MINES = 5  # the race's mines came back (match.setup.rules.mineRegenMs gives a step or more)
VERSION_SEATS = 6  # a seat raced a pack of its own (match.setup.packs, a seat's pack)
VERSION_GRID = 7  # 0.4.0's set-up: the race started on the coordinator's grid (match.setup.grid) or raced wit
VERSION_WRITTEN = 7
VERSIONS = (2, 3, 4, 5, 6, 7)
FEATURES = ("stats", "custom", "mines", "seat_packs", "grid")
HEAD_SIZE = 10
FRAMES_SIZE = 12
LINEUP_SIZE = 124
LINEUP_LEAST = 122
RECORD_SIZE = 6
CHECKSUM_SIZE = 4
RESULTS_TAIL = 8
MAX_BYTES = 268435456
MAX_STEPS = 1296000
MAX_SEATS = 30
HEADER_KEYS = ("match", "seat", "mask", "delay", "flow", "rubberBand", "mod_sha1", "mod_commit", "game", "engine", "module_sha1", "recorded", "practice")
RESULT_KEYS = ("seat", "rank", "finished", "out", "laps", "timeMs", "bestLapMs")
# the lineup's block: (name, offset, count, struct format of one)
LINEUP_FIELDS = (("machines", 0, 30, "B"), ("ranks", 30, 30, "B"), ("settings", 60, 30, "h"), ("control_mode", 120, 1, "B"), ("rel_d70", 121, 1, "B"),)


def played(version):
    """Whether the game plays a file of this version."""
    return version in VERSIONS


def version_of(**features):
    """The version a race of these features (FEATURES: True or False) is, and the only one its file may be: the
    highest whose feature it holds, else the first."""
    unknown = set(features) - set(FEATURES)
    if unknown:
        raise ValueError(f"no feature {sorted(unknown)}")
    if features.get("grid"):
        return VERSION_GRID
    if features.get("seat_packs"):
        return VERSION_SEATS
    if features.get("mines"):
        return VERSION_MINES
    if features.get("custom"):
        return VERSION_CUSTOM
    if features.get("stats"):
        return VERSION_STATS
    return VERSION_PLAIN


def lineup(block):
    """The lineup's block as a dict of its fields (a block shorter than LINEUP_SIZE reads 0 after its end)."""
    b = bytes(block[:LINEUP_SIZE]).ljust(LINEUP_SIZE, b"\0")
    out = {}
    for name, at, count, one in LINEUP_FIELDS:
        values = struct.unpack_from(f">{count}{one}", b, at)
        out[name] = list(values) if count > 1 else values[0]
    return out


class Replay:
    """A file's parts, as far as the file has them (each read only when the one before it is whole). header and
    results are the JSON's bytes (None: not in the file); lineup is the block's bytes and lineup_part the bytes
    from the frames' part to the first step; steps is [(the seats' records, the checksum's 4 bytes)] of the
    whole steps; whole says the steps' bytes are whole steps."""

    def __init__(self):
        self.marked, self.version, self.header_length, self.header = False, 0, 0, None
        self.frames, self.frames_marked, self.mask, self.seat, self.seats = False, False, 0, 0, []
        self.has_lineup, self.lineup_length, self.lineup, self.lineup_part = False, 0, b"", b""
        self.results, self.steps_at, self.steps_end, self.steps, self.whole = None, 0, 0, [], False


def parse(data):
    """A replay file's bytes, in their parts (Replay)."""
    r = Replay()
    if len(data) < HEAD_SIZE or data[:4] != MARK:
        return r
    r.marked = True
    r.version, r.header_length = struct.unpack_from(">HI", data, 4)
    frames_at = HEAD_SIZE + r.header_length
    if frames_at > len(data):
        return r
    r.header = bytes(data[HEAD_SIZE:frames_at])
    if len(data) - frames_at < FRAMES_SIZE:
        return r
    r.frames, r.frames_marked = True, data[frames_at:frames_at + 4] == FRAMES_MARK
    r.mask, r.seat = struct.unpack_from(">II", data, frames_at + 4)
    r.seats = [i for i in range(32) if r.mask >> i & 1]
    frames_end = frames_at + FRAMES_SIZE
    r.steps_at, r.steps_end = frames_end, len(data)
    if len(data) - frames_end >= RESULTS_TAIL and data[-4:] == RESULTS_MARK:
        length = struct.unpack_from(">I", data, len(data) - 8)[0]
        if length + RESULTS_TAIL <= len(data) - frames_end:
            r.steps_end = len(data) - RESULTS_TAIL - length
            r.results = bytes(data[r.steps_end:len(data) - RESULTS_TAIL])
    if r.steps_end - frames_end >= 8 and data[frames_end:frames_end + 4] == LINEUP_MARK:
        r.has_lineup = True
        r.lineup_length = struct.unpack_from(">I", data, frames_end + 4)[0]
        r.steps_at = frames_end + 8 + r.lineup_length
        r.lineup = bytes(data[frames_end + 8:min(r.steps_at, r.steps_end)])
    r.lineup_part = bytes(data[frames_end:min(r.steps_at, r.steps_end)])
    row = len(r.seats) * RECORD_SIZE
    size = row + CHECKSUM_SIZE
    if r.seats and r.steps_end >= r.steps_at:
        r.steps = [(bytes(data[at:at + row]), bytes(data[at + row:at + size]))
                   for at in range(r.steps_at, r.steps_end - size + 1, size)]
        r.whole = (r.steps_end - r.steps_at) % size == 0
    return r


def read(path):
    """The replay file at path, in its parts (Replay)."""
    with open(path, "rb") as f:
        return parse(f.read())
